using System.Text.Json;
using Avalonia.Threading;
using VisualRelay.App.Services;
using VisualRelay.App.ViewModels;
using VisualRelay.App.Views;
using VisualRelay.Core.Queue;
using VisualRelay.Core.Tasks;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

/// <summary>
/// Tests for the "Reset" command — archiving a flagged task's run directory
/// and returning it to Pending without starting a run.
/// </summary>
[Collection("Headless")]
public sealed class MainWindowViewModelResetTests
{
    [AvaloniaFact]
    public async Task ResetFlaggedTask_ArchivesRunDir_AndShowsPending()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("flagged-task", "# Flagged Task\n\nNeeds work.");

        // Create fake run state under .relay/<taskId>/ — simulates a flagged run.
        var runDir = Path.Combine(repo.Root, ".relay", "flagged-task");
        Directory.CreateDirectory(runDir);
        repo.WriteNeedsReview("flagged-task", "stage 5 verify failed");
        File.WriteAllText(Path.Combine(runDir, "flagged-work.bundle"), "bundled work content");
        File.WriteAllText(Path.Combine(runDir, "status.json"), "[{\"stage\":1,\"status\":\"Done\"}]");

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };
        await viewModel.LoadInitialAsync();

        var task = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Assert.True(task.NeedsReview, "task must be flagged before reset");
        Assert.Equal("Needs review", task.StateLabel);

        viewModel.SelectedTask = task;
        Dispatcher.UIThread.RunJobs();
        await (viewModel.LastSelectionLoad ?? Task.CompletedTask);

        // Command must be available for a flagged task.
        Assert.True(viewModel.ResetSelectedTaskCommand.CanExecute(null));

        // Act: reset the flagged task.
        await viewModel.ResetSelectedTaskCommand.ExecuteAsync(null);
        Dispatcher.UIThread.RunJobs();

        // Assert: the task now shows Pending (no NeedsReview).
        task = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Assert.False(task.NeedsReview, "task must no longer be flagged after reset");
        Assert.Equal("Pending", task.StateLabel);

        // Assert: the live run directory is gone.
        Assert.False(Directory.Exists(runDir), "live run directory must be renamed away");

        // Assert: an archive directory exists with the bundle intact.
        var archiveDirs = Directory.GetDirectories(Path.Combine(repo.Root, ".relay"), "flagged-task.reset-*");
        Assert.Single(archiveDirs);
        var archiveDir = archiveDirs[0];
        Assert.True(File.Exists(Path.Combine(archiveDir, "flagged-work.bundle")),
            "flagged-work.bundle must be preserved in the archive");
        Assert.True(File.Exists(Path.Combine(archiveDir, "status.json")),
            "status.json must be preserved in the archive");
        Assert.True(File.Exists(Path.Combine(archiveDir, "NEEDS-REVIEW")),
            "NEEDS-REVIEW must be preserved in the archive");

        // Assert: NEEDS-REVIEW is not on the live path.
        Assert.False(File.Exists(Path.Combine(repo.Root, ".relay", "flagged-task", "NEEDS-REVIEW")),
            "NEEDS-REVIEW must not exist on the live path after reset");
    }

    [AvaloniaFact]
    public async Task CanReset_FalseWhenNotFlagged()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("pending-task", "# Pending Task\n");

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };
        await viewModel.LoadInitialAsync();

        viewModel.SelectedTask = viewModel.Tasks.Single(t => t.Id == "pending-task");
        Dispatcher.UIThread.RunJobs();
        await (viewModel.LastSelectionLoad ?? Task.CompletedTask);

        // A non-flagged task must be rejected by the can-execute gate.
        Assert.False(viewModel.NeedsReview);
        Assert.False(viewModel.ResetSelectedTaskCommand.CanExecute(null));
    }

    [AvaloniaFact]
    public async Task CanReset_FalseWhenShowArchive()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("flagged-task", "# Flagged Task\n");
        repo.WriteNeedsReview("flagged-task", "stage 5 verify failed");

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };
        await viewModel.LoadInitialAsync();

        viewModel.SelectedTask = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Dispatcher.UIThread.RunJobs();
        await (viewModel.LastSelectionLoad ?? Task.CompletedTask);

        // Before: command is enabled for a flagged task.
        Assert.True(viewModel.ResetSelectedTaskCommand.CanExecute(null));

        // Set ShowArchive — the gate should block.
        viewModel.ShowArchive = true;
        Dispatcher.UIThread.RunJobs();

        Assert.False(viewModel.ResetSelectedTaskCommand.CanExecute(null));
    }

    [AvaloniaFact]
    public async Task CanReset_TrueEvenWhenIsBusy()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("flagged-task", "# Flagged Task\n");
        repo.WriteNeedsReview("flagged-task", "stage 5 verify failed");

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };
        await viewModel.LoadInitialAsync();

        viewModel.SelectedTask = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Dispatcher.UIThread.RunJobs();
        await (viewModel.LastSelectionLoad ?? Task.CompletedTask);

        // Before: command is enabled.
        Assert.True(viewModel.ResetSelectedTaskCommand.CanExecute(null));

        // Set IsBusy — Reset must NOT gate on IsBusy (must work while another task runs).
        viewModel.IsBusy = true;
        Dispatcher.UIThread.RunJobs();

        Assert.True(viewModel.ResetSelectedTaskCommand.CanExecute(null),
            "Reset must be available even when IsBusy (another task running)");
    }

    [AvaloniaFact]
    public async Task CanReset_TrueEvenWhenAnotherTaskIsRunning()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("flagged-task", "# Flagged Task\n");
        repo.WriteNestedTask("running-task", "# Running Task\n");
        repo.WriteNeedsReview("flagged-task", "stage 5 verify failed");

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };
        await viewModel.LoadInitialAsync();

        // Simulate task B running via the drain lifecycle hook.
        viewModel.CreateDrainLifecycleCallbacks().OnExecuteStarted?.Invoke("running-task");
        Dispatcher.UIThread.RunJobs();

        // Select the flagged task A.
        viewModel.SelectedTask = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Dispatcher.UIThread.RunJobs();
        await (viewModel.LastSelectionLoad ?? Task.CompletedTask);

        // Reset must be available even while another task is running.
        Assert.True(viewModel.ResetSelectedTaskCommand.CanExecute(null),
            "Reset must be available even while another task is running");
    }

    [AvaloniaFact]
    public void CanReset_FalseWhenNoTaskSelected()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };

        // No selected task → command should be disabled.
        Assert.Null(viewModel.SelectedTask);
        Assert.False(viewModel.ResetSelectedTaskCommand.CanExecute(null));
    }

    [AvaloniaFact]
    public async Task Reset_HumanGui_ShowsConfirmation_AndHonorsCancel()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("flagged-task", "# Flagged Task\n");
        repo.WriteNeedsReview("flagged-task", "stage 5 verify failed");

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };
        await viewModel.LoadInitialAsync();

        viewModel.SelectedTask = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Dispatcher.UIThread.RunJobs();
        await (viewModel.LastSelectionLoad ?? Task.CompletedTask);

        // Human path: a real (non-API) invocation must consult the modal delegate
        // and honor Cancel (return false → no reset).
        var dialogShown = false;
        viewModel.ShowConfirmationAsync = (_, _, _) => { dialogShown = true; return Task.FromResult(false); };

        await viewModel.ResetSelectedTaskCommand.ExecuteAsync(null);
        Dispatcher.UIThread.RunJobs();

        Assert.True(dialogShown, "a real button click must still open the confirmation modal");
        // Cancel aborted the reset — task is still flagged.
        var task = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Assert.True(task.NeedsReview, "task must remain flagged after cancel");
    }

    [AvaloniaFact]
    public async Task Reset_HumanGui_ConfirmsAndResets()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("flagged-task", "# Flagged Task\n");
        repo.WriteNeedsReview("flagged-task", "stage 5 verify failed");

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };
        await viewModel.LoadInitialAsync();

        viewModel.SelectedTask = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Dispatcher.UIThread.RunJobs();
        await (viewModel.LastSelectionLoad ?? Task.CompletedTask);

        var dialogShown = false;
        viewModel.ShowConfirmationAsync = (title, message, confirmLabel) =>
        {
            dialogShown = true;
            Assert.Contains("Reset", title);
            Assert.Contains("flagged-task", message);
            Assert.Equal("Reset", confirmLabel);
            return Task.FromResult(true);
        };

        await viewModel.ResetSelectedTaskCommand.ExecuteAsync(null);
        Dispatcher.UIThread.RunJobs();

        Assert.True(dialogShown, "confirmation modal must be shown for human GUI path");
        var task = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Assert.False(task.NeedsReview, "task must be reset after confirm");
    }

    [AvaloniaFact]
    public async Task Reset_ViaApi_WithoutConfirm_Returns409()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("flagged-task", "# Flagged Task\n");
        repo.WriteNeedsReview("flagged-task", "stage 5 verify failed");

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };
        await viewModel.LoadInitialAsync();

        await Dispatcher.UIThread.InvokeAsync(() =>
            viewModel.SelectedTask = viewModel.Tasks.Single(t => t.Id == "flagged-task"));
        Dispatcher.UIThread.RunJobs();
        await (viewModel.LastSelectionLoad ?? Task.CompletedTask);

        var window = new MainWindow { DataContext = viewModel };
        var api = new ControlApi(viewModel, window);

        var dialogShown = false;
        viewModel.ShowConfirmationAsync = (_, _, _) => { dialogShown = true; return Task.FromResult(true); };

        // Invoke without confirm body.
        var (status, json) = await api.InvokeCommandAsync("reset-selected", null);
        Dispatcher.UIThread.RunJobs();

        Assert.Equal(409, status);
        using (var doc = JsonDocument.Parse(json))
        {
            Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
            Assert.Equal("confirmation required", doc.RootElement.GetProperty("error").GetString());
        }

        Assert.False(dialogShown, "a refused destructive command must not open a dialog");

        // No effect: the task is still flagged.
        var task = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Assert.True(task.NeedsReview, "task must remain flagged after refused API call");
    }

    [AvaloniaFact]
    public async Task Reset_ViaApi_WithConfirm_CompletesAndResets_WithoutDialog()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("flagged-task", "# Flagged Task\n");
        repo.WriteNeedsReview("flagged-task", "stage 5 verify failed");

        var viewModel = new MainWindowViewModel(repo.Env) { RootPath = repo.Root, ShowConfirmationAsync = null };
        await viewModel.LoadInitialAsync();

        await Dispatcher.UIThread.InvokeAsync(() =>
            viewModel.SelectedTask = viewModel.Tasks.Single(t => t.Id == "flagged-task"));
        Dispatcher.UIThread.RunJobs();
        await (viewModel.LastSelectionLoad ?? Task.CompletedTask);

        var window = new MainWindow { DataContext = viewModel };
        var api = new ControlApi(viewModel, window);

        var dialogShown = false;
        viewModel.ShowConfirmationAsync = (_, _, _) => { dialogShown = true; return Task.FromResult(true); };

        var (status, json) = await api.InvokeCommandAsync("reset-selected", "{\"confirm\":true}");
        Dispatcher.UIThread.RunJobs();

        Assert.Equal(200, status);
        using (var doc = JsonDocument.Parse(json))
        {
            Assert.True(doc.RootElement.GetProperty("ok").GetBoolean());
        }

        Assert.False(dialogShown, "API-driven reset must not open the interactive confirmation dialog");

        // Effect: the task is now Pending.
        var task = viewModel.Tasks.Single(t => t.Id == "flagged-task");
        Assert.False(task.NeedsReview, "task must be reset after confirmed API call");
    }

    [AvaloniaFact]
    public async Task Reset_RemovesFromSeenIds_ActiveDrain()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("task-a", "# Task A\n");
        repo.WriteNestedTask("task-b", "# Task B\n");
        // Flag task B so it wouldn't be collected normally.
        repo.WriteNeedsReview("task-b", "stage 5 verify failed");

        var controller = new RelayQueueController(repo.Root, new NoopTaskRunner());
        await controller.RefreshAsync();

        // Manually mark task B as no longer NeedsReview (simulating what happens after a reset).
        var taskB = controller.Tasks.Single(t => t.Id == "task-b");
        var idxB = controller.Tasks.IndexOf(taskB);
        controller.Tasks[idxB] = taskB with { ReviewReason = null };

        // Remove from seen — simulating what Reset does during an active drain.
        controller.RemoveFromSeen("task-b");

        // After RemoveFromSeen, the task should be collectable (no longer NeedsReview and not in seenIds).
        // We verify this by checking that the task is now Pending.
        taskB = controller.Tasks.Single(t => t.Id == "task-b");
        Assert.False(taskB.NeedsReview, "task must be Pending after simulated reset");

        // The controller's RemoveFromSeen must not throw even if no drain is active.
        controller.RemoveFromSeen("nonexistent");
    }

    [AvaloniaFact]
    public async Task ArchiveDirectory_InvisibleToListing()
    {
        using var repo = TestRepository.Create();
        repo.WriteConfig("dotnet test", []);
        repo.WriteNestedTask("archive-test", "# Archive Test\n");
        repo.WriteNeedsReview("archive-test", "stage 5 verify failed");

        // Create a fake .reset-* archive dir to simulate a prior reset.
        var archiveDir = Path.Combine(repo.Root, ".relay", "archive-test.reset-20260101T120000");
        Directory.CreateDirectory(archiveDir);
        File.WriteAllText(Path.Combine(archiveDir, "NEEDS-REVIEW"), "old reason\n");
        File.WriteAllText(Path.Combine(archiveDir, "status.json"), "[]");

        var repository = new RelayTaskRepository(repo.Root);
        var tasks = await repository.ListAsync();

        // The task should appear exactly once as Pending (NEEDS-REVIEW is still in the live path).
        var matching = tasks.Where(t => t.Id == "archive-test").ToArray();
        Assert.Single(matching, "archive-test must appear exactly once in the listing");
        Assert.True(matching[0].NeedsReview, "task should still be flagged (NEEDS-REVIEW in live path)");

        // Now actually reset: rename the live dir to a .reset-* archive.
        repository.ResetTask("archive-test");

        // Assert the live dir is gone and archive exists.
        var liveDir = Path.Combine(repo.Root, ".relay", "archive-test");
        Assert.False(Directory.Exists(liveDir), "live run dir must be renamed away");

        // After reset, list again — task must be Pending.
        tasks = await repository.ListAsync();
        matching = tasks.Where(t => t.Id == "archive-test").ToArray();
        Assert.Single(matching, "archive-test must still appear exactly once");
        Assert.False(matching[0].NeedsReview, "task should be Pending after reset");
        Assert.Equal("Pending", matching[0].StateLabel);

        // Multiple .reset-* dirs must not affect the listing.
        var archiveDir2 = Path.Combine(repo.Root, ".relay", "archive-test.reset-20260102T120000");
        Directory.CreateDirectory(archiveDir2);
        File.WriteAllText(Path.Combine(archiveDir2, "NEEDS-REVIEW"), "another reason\n");

        tasks = await repository.ListAsync();
        matching = tasks.Where(t => t.Id == "archive-test").ToArray();
        Assert.Single(matching, "archive-test must still appear exactly once with multiple archives");
        Assert.False(matching[0].NeedsReview, "archived NEEDS-REVIEW must not affect listing");
    }

    /// <summary>
    /// A task runner that does nothing — used for tests that only exercise
    /// the controller's queue management, not actual execution.
    /// </summary>
    private sealed class NoopTaskRunner : IRelayTaskRunner
    {
        public Task<RelayTaskOutcome> RunTaskAsync(string rootPath, string taskId,
            CancellationToken cancellationToken = default)
            => Task.FromResult(new RelayTaskOutcome(taskId, RelayTaskOutcomeStatus.Committed, "hash", "commit", null));
    }
}

