namespace VisualRelay.Core.Tasks;

public sealed partial class RelayTaskRepository
{
    /// <summary>
    /// Archives the entire run-state directory for a task by renaming it to a
    /// timestamped archive path (<c>.relay/{id}.reset-{utc-stamp}/</c>). This
    /// removes the NEEDS-REVIEW marker, stage state, logs, and flagged-work
    /// bundle from the live path atomically — the next run starts at stage 1
    /// because status.json is gone. The archive preserves all evidence on disk.
    /// If the run directory does not exist, this is a no-op.
    /// Pattern: <see cref="Queue.RestartHandoff.MarkConsumed"/>.
    /// </summary>
    public void ResetTask(string taskId)
    {
        var liveDir = Path.Combine(RootPath, ".relay", taskId);
        if (!Directory.Exists(liveDir))
            return;

        var stamp = DateTimeOffset.UtcNow.ToString("yyyyMMddTHHmmss");
        var archiveDir = Path.Combine(RootPath, ".relay", $"{taskId}.reset-{stamp}");

        // Directory.Move is atomic within a volume: a concurrent scan sees either
        // the pre-rename (flagged) view or the post-rename (pending) view, never a
        // partial directory.
        Directory.Move(liveDir, archiveDir);
    }
}

using CommunityToolkit.Mvvm.Input;
using VisualRelay.Core.Tasks;

namespace VisualRelay.App.ViewModels;

public partial class MainWindowViewModel
{
    [RelayCommand(CanExecute = nameof(CanResetSelectedTask))]
    private async Task ResetSelectedTaskAsync()
    {
        if (SelectedTask is null)
            return;

        // Confirm via the shared seam (auto-resolves when headless or driven via
        // the pre-confirmed control API; opens the modal for a human click).
        var confirmed = await ConfirmAsync(
            "Reset task",
            $"Return \"{SelectedTask.Id}\" to Pending? The flagged run directory will be archived. The task will be eligible at the next drain boundary.",
            "Reset");
        if (!confirmed)
            return;

        // Intentionally does NOT wrap in RunBusyAsync — Reset must work while
        // another task is running (IsBusy=true). The repository rename is fast
        // and safe to run from the UI thread.
        new RelayTaskRepository(RootPath).ResetTask(SelectedTask.Id);

        // Evict from the in-flight drain's seen set so the task becomes
        // eligible at the next Sequential/RestartBetweenTasks boundary.
        _activeDrainController?.RemoveFromSeen(SelectedTask.Id);

        await ReloadTaskListAsync();
        StatusText = FormatQueueStatus();
    }

    private bool CanResetSelectedTask() =>
        SelectedTask is not null &&
        SelectedTask.NeedsReview &&
        !ShowArchive;
    // Note: deliberately does NOT gate on IsBusy or _runningTaskIds — Reset
    // is designed to work while another task is running.

    public bool IsResetButtonVisible =>
        SelectedTask is not null && SelectedTask.NeedsReview && !ShowArchive;
}

